import {flightRoute,routePoint} from './geography.js?v=art2';
import {FlightAudio} from './flight-audio.js';
const flightAudio = new FlightAudio();
import {cities,clothes,weatherIcons,warmth,checkBag,itemProblem} from './data.js?v=art2';
const $=s=>document.querySelector(s);
const flagImage=c=>`<img class="country-flag" src="./assets/flags/${c.flag}.svg" alt="${c.country} flag" width="32" height="24">`;
let selected=cities.find(c=>c.id==='paris'), current=cities.find(c=>c.id==='taipei'),day=0, stage='choose',bag=new Set(), sound=true,spoken='Hello, explorer! Where shall we go?',flying=false;
let flightEndsAt=0;
let stamps=[];
try{stamps=JSON.parse(localStorage.getItem('little-world-stamps')||'[]').filter(id=>cities.some(c=>c.id===id));}catch{stamps=[];}
function say(text){spoken=text;$('#spoken-text').textContent=text;if(!sound)return;if(!('speechSynthesis'in window)){ $('#speech-status').textContent='Voice is not available in this browser. Read the words and try Chrome or Edge.';return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.8;const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang==='en-US')||voices.find(v=>v.lang.startsWith('en'))||null;u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))$('#speech-status').textContent='Tap Listen again to hear the words. Check your device sound.';};speechSynthesis.speak(u);}
if('speechSynthesis'in window){speechSynthesis.getVoices();speechSynthesis.addEventListener('voiceschanged',()=>speechSynthesis.getVoices());}
document.addEventListener('pointerdown',()=>{if(sound)flightAudio.unlock();},{passive:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden){flightAudio.stop();if('speechSynthesis' in window)speechSynthesis.cancel();}});
window.addEventListener('pagehide',()=>flightAudio.stop());
const weather=()=>selected.weather[day];
const weatherSentence=()=>`It is ${weather()[1]} and ${warmth(weather()[0])}. It is ${weather()[0]} degrees.`;
const listen=text=>{const b=document.createElement('button');b.className='speaker';b.textContent='♫';b.setAttribute('aria-label',`Listen: ${text}`);b.onclick=()=>say(text);return b;};
function updateStamps(){$('#stamp-count').textContent=`${stamps.length} / 15`;}
function renderMap(){
 $('#markers').innerHTML=cities.map(c=>`<button class="pin ${c.label?'label-'+c.label:''} ${selected.id===c.id?'selected':''}" style="left:${c.x}%;top:${c.y}%" data-city="${c.id}" aria-label="Choose ${c.name}" aria-pressed="${selected.id===c.id}"><span class="dot"></span><span class="pin-label">${c.name}</span></button>`).join('');
 $('#city-list').innerHTML=cities.map(c=>`<button class="city-chip ${c.id===selected.id?'selected':''}" data-city="${c.id}" aria-pressed="${c.id===selected.id}">${flagImage(c)} ${c.name}${stamps.includes(c.id)?' ✓':''}</button>`).join('');
 document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>selectCity(b.dataset.city));
 $('#city-select').innerHTML=cities.map(c=>`<option value="${c.id}" ${c.id===selected.id?'selected':''}>${c.name}</option>`).join('');
 $('#current-location').textContent=`⌂ ${current.name}`;
}
function selectCity(id){if(flying)return;const next=cities.find(c=>c.id===id);if(!next)throw new Error('Unknown city');selected=next;day=0;renderMap();renderDestination();say(`Let's go to ${selected.say||selected.name}! ${weatherSentence()}`);}
function renderDestination(){const [temp,sky]=weather();$('#destination').innerHTML=`<div class="destination-image"><img src="./assets/cities/${selected.id}.webp" alt="Illustration of ${selected.name}"><span class="postcard-label">YOUR DESTINATION</span></div><div class="destination-body"><div class="destination-title"><h2>${selected.name}</h2></div><p class="country-line">${flagImage(selected)} ${selected.country} · ${Math.abs(selected.lat).toFixed(1)}° ${selected.lat>=0?'N':'S'}</p><button class="weather-day" id="change-day">Practice day ${day+1} ↻</button><div class="weather-box"><span class="weather-icon">${weatherIcons[sky]}</span><div><div class="temperature">${temp}°C</div><div class="weather-desc">${sky[0].toUpperCase()+sky.slice(1)} & ${warmth(temp)}</div></div></div><p class="mini-note">Practice weather, not a live forecast.</p><button class="primary full" id="start-pack">Let's pack! <span aria-hidden="true"> →</span></button></div>`;$('.destination-title').append(listen(`${selected.say||selected.name}. ${weatherSentence()}`));$('#start-pack').onclick=startPack;$('#change-day').onclick=()=>{day=(day+1)%3;renderDestination();say(weatherSentence());};}
function showStage(next){stage=next;$('#choose-screen').hidden=next!=='choose'&&next!=='fly';$('#pack-screen').hidden=next!=='pack';$('#arrival-screen').hidden=next!=='arrival';document.querySelectorAll('.step').forEach(s=>s.classList.toggle('active',s.dataset.step===(next==='arrival'?'fly':next)));window.scrollTo({top:0,behavior:'instant'});}
function startPack(){bag.clear();showStage('pack');renderPack();say(`Let's pack for ${selected.say||selected.name}. ${weatherSentence()} Put clothes in your bag.`);}
function clothingHTML(c,inBag=false){return `<button class="clothing ${bag.has(c.id)&&!inBag?'packed':''}" data-item="${c.id}" ${inBag?'data-remove="true"':''} draggable="${!inBag&&!matchMedia('(pointer: coarse)').matches}" aria-label="${inBag?'Remove':'Pack'} ${c.name}" ${!inBag?`aria-pressed="${bag.has(c.id)}"`:''}><img src="./assets/clothes/${c.id}.png" alt=""><span>${c.name}</span>${bag.has(c.id)&&!inBag?'<span class="check-badge">✓</span>':''}</button>`;}
function renderPack(){const [temp,sky]=weather();$('#pack-screen').innerHTML=`<div class="page-title"><div><p class="eyebrow">GET READY, EXPLORER!</p><h1>What goes in your bag?</h1><p>${flagImage(selected)} ${selected.name} · ${weatherIcons[sky]} ${temp}°C · ${sky} & ${warmth(temp)}</p></div><button id="back-map" class="quiet">← Map</button></div><div class="pack-layout"><section class="closet"><h2>My clothes</h2><p class="packing-needs">Tap clothes to pack. Tap again to take them out.<br>Take a top, pants or shorts, and shoes or boots.</p><div class="clothes-grid">${clothes.map(c=>clothingHTML(c)).join('')}</div></section><section class="bag-panel"><div class="bag-handle"></div><div id="suitcase" class="suitcase" aria-label="Suitcase drop area"><div class="bag-title">My little travel bag</div><div class="bag-items">${bag.size?clothes.filter(c=>bag.has(c.id)).map(c=>clothingHTML(c,true)).join(''):'<div class="empty-bag">Your adventure starts here.<br>Let’s put some clothes in!</div>'}</div></div><div id="feedback" class="feedback" role="status">${bag.size?`${bag.size} items packed. Tap an item in the bag to take it out.`:'Look at the weather. What do you need?'}</div><div class="pack-actions"><button class="primary full" id="check-bag">Check my bag ✓</button></div></section></div>`;
 $('#back-map').onclick=()=>{showStage('choose');say('Pick a city. Check the weather.');};
 document.querySelectorAll('[data-item]').forEach(b=>{b.onclick=()=>toggleItem(b.dataset.item);b.ondragstart=e=>e.dataTransfer.setData('text/plain',b.dataset.item);});
 $('#suitcase').ondragover=e=>e.preventDefault();$('#suitcase').ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(clothes.some(c=>c.id===id)&&!bag.has(id))toggleItem(id);};$('#check-bag').onclick=check;
}
function feedback(text,error=false){$('#feedback').textContent=text;$('#feedback').classList.toggle('error',error);let notice=$('#mobile-feedback');if(!notice){notice=document.createElement('div');notice.id='mobile-feedback';$('#pack-screen .page-title').after(notice);}notice.textContent=text;notice.className=error?'mobile-feedback error':'mobile-feedback';say(text);}
function toggleItem(id){if(stage!=='pack')return;const item=clothes.find(c=>c.id===id);if(!item)return;if(bag.has(id)){bag.delete(id);renderPack();feedback(`Take out the ${item.name}.`);return;}const problem=itemProblem(id,weather());if(problem){feedback(problem,true);return;}bag.add(id);renderPack();feedback(`Good! Pack the ${item.name}.`);}
function check(){const issues=checkBag([...bag],weather());if(issues.length){feedback(issues.join(' '),true);return;}feedback('Great job! Your bag is ready. Let’s fly!');const b=document.createElement('button');b.className='primary full';b.id='takeoff';b.textContent='Let’s fly! ✈';b.onclick=fly;$('.pack-actions').replaceChildren(b);}
function fly(){if(flying||stage!=='pack'||checkBag([...bag],weather()).length)return;flying=true;showStage('fly');$('#choose-screen').classList.add('flight-mode');$('#choose-screen .page-title h1').textContent=`Flying to ${selected.name}!`;$('#choose-screen .page-title p:not(.eyebrow)').textContent='Look out the window. Here we go!';$('#plane').hidden=false;$('#plane').style.left=`${current.x}%`;$('#plane').style.top=`${current.y}%`;
 const route=flightRoute(current,selected);$('#route-path').setAttribute('d',route.path);
 say(`Good job! Let's fly to ${selected.say||selected.name}!`);
 const duration=matchMedia('(prefers-reduced-motion: reduce)').matches?1200:6500,start=performance.now();
 flightEndsAt=start+duration;flightAudio.setEnabled(sound);flightAudio.start(duration/1000);
 function animate(now){const t=Math.min(1,(now-start)/duration),{x,y}=routePoint(route,t);$('#plane').style.left=`${x/10}%`;$('#plane').style.top=`${y/5}%`;$('#plane').style.transform=`translate(-50%,-50%) scaleX(${route.end.x<route.start.x?-1:1}) rotate(${Math.sin(t*Math.PI)*-8}deg)`;if(t<1)requestAnimationFrame(animate);else arrive();}requestAnimationFrame(animate);
}
function arrive(){flightAudio.stop();flying=false;current=selected;if(!stamps.includes(selected.id)){stamps.push(selected.id);try{localStorage.setItem('little-world-stamps',JSON.stringify(stamps));}catch{}}updateStamps();$('#plane').hidden=true;$('#route-path').setAttribute('d','');$('#choose-screen').classList.remove('flight-mode');$('#choose-screen .page-title h1').textContent='Where shall we go?';$('#choose-screen .page-title p:not(.eyebrow)').textContent='Pick a city. Check the weather. Pack your bag!';showStage('arrival');$('#arrival-screen').innerHTML=`<article class="arrival"><div class="arrival-scene"><img src="./assets/cities/${selected.id}.webp" alt="${selected.name} scenery"><img class="arrival-plane" src="./assets/plane.png" alt="Your student explorer in the plane"></div><div class="arrival-copy"><div class="stamp">${flagImage(selected)}<br>${selected.name.toUpperCase()}<br>✧ VISITED ✧</div><p class="eyebrow">A NEW PLACE. A NEW ADVENTURE.</p><h1>Hello, ${selected.name}!</h1><p>${selected.landmark}</p><p>You packed for ${weather()[1]} weather. Well done!</p><div class="arrival-actions"><button id="listen-city" class="quiet">♫ Listen & say</button><button id="next-trip" class="primary">Next adventure →</button></div></div></article>`;$('#listen-city').onclick=()=>say(`Hello, ${selected.say||selected.name}! ${selected.landmark}`);$('#next-trip').onclick=()=>{showStage('choose');renderMap();renderDestination();say('Where shall we go next?');};say(`Welcome to ${selected.say||selected.name}! ${selected.landmark} You did a great job!`);}
$('#random').onclick=()=>{const pool=cities.filter(c=>c.id!==selected.id&&c.id!==current.id);selectCity(pool[Math.floor(Math.random()*pool.length)].id);};
$('#sound').onclick=()=>{sound=!sound;flightAudio.setEnabled(sound);if(sound&&flying)flightAudio.start(Math.max(.1,(flightEndsAt-performance.now())/1000));$('#sound').textContent=sound?'♫ Sound on':'♫ Sound off';$('#sound').setAttribute('aria-pressed',String(sound));if(!sound&&'speechSynthesis'in window)speechSynthesis.cancel();if(sound)say(spoken);};$('#repeat').onclick=()=>{sound=true;flightAudio.setEnabled(true);$('#sound').textContent='♫ Sound on';$('#sound').setAttribute('aria-pressed','true');say(spoken);};
$('#city-select').onchange=e=>selectCity(e.target.value);
const modal=$('#modal');$('#close-modal').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
$('#passport').onclick=()=>{$('#modal-content').innerHTML=`<p class="eyebrow">MY LITTLE WORLD</p><h1>My passport</h1><p>${stamps.length} of 15 cities visited. Where will you go next?</p><div class="passport-grid">${cities.map(c=>`<div class="passport-stamp ${stamps.includes(c.id)?'earned':''}"><span>${flagImage(c)}</span>${c.name}<br>${stamps.includes(c.id)?'✓ Visited':'Not yet'}</div>`).join('')}</div>`;modal.showModal();say(`Your passport. You visited ${stamps.length} cities.`);};
$('#teacher').onclick=()=>{$('#modal-content').innerHTML='<div class="teacher-copy"><p class="eyebrow">TEACHER NOTES</p><h2>小小世界旅行家</h2><p>適合臺灣國小四年級，使用簡單衣物、天氣單字及短句。點城市、物品或 Listen again 即可聽英文；語速為一般速度的 0.8 倍。</p><ul><li>每座城市有 3 組<strong>教學用模擬天氣</strong>，按 Practice day 切換。不是即時預報，也不表示該城市每天的氣候。</li><li>先選目的地 → 打包 → Check my bag → Let’s fly → 看景點、收集護照章。點擊與滑鼠拖曳都可放入衣物；再次點擊可取出。</li><li>基本衣物：T-shirt 或 sweater、pants 或 shorts、shoes 或 boots。10°C 以下要 coat；0°C 以下還要 gloves；11–19°C 要 sweater 或 coat。25°C 以上不收厚重冬衣。</li><li>rainy 要 umbrella；snowy 要 boots；sunny 要 hat 或 sunglasses。windy 不收 umbrella；cold 不收 shorts。其他合適的額外衣物可以攜帶。</li><li>英文語音使用裝置內建語音。適合 iPad Safari，橫直向皆可；先點按遊戲啟用語音與飛行音效，Sound off 可全部靜音；需裝有英文語音。所有語音同時顯示文字。</li><li>地圖保留手繪插畫風格，城市位置依插畫海岸線校準；城市標記與飛機起降點共用座標。地圖非等比例地理投影，航線為教學示意。都市插圖是教學示意。護照只存在此瀏覽器，不蒐集學生個資。手機可左右滑動地圖。</li></ul></div>';modal.showModal();};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_travel_game_state',description:'Read the selected destination, practice weather, bag and game stage.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({stage,city:selected.id,weather:weather(),bag:[...bag],visited:[...stamps]})})).catch(()=>{});}catch{}}
renderMap();renderDestination();updateStamps();
